type State = "idle" | "joining" | "joined" | "ended";

export class JoinSignaling {
  state: State = "idle";

  beginJoin(): void {
    this.state = "joining";
  }

  onJoinAccepted(): void {
    this.state = "joined";
  }

  endMeeting(): void {
    this.state = "ended";
  }
}

type State = "idle" | "joining" | "joined" | "reconnecting" | "leaving" | "ended";
type Listener = () => void;
interface Link { onOpen(listener: Listener): void; onClose(listener: Listener): void; connect(): void; }

export class MeetingSignaling {
  state: State = "idle";
  private link?: Link;
  constructor(private readonly createLink: () => Link) {}

  join(): void {
    this.state = "joining";
    this.openLink();
  }

  private openLink(): void {
    const link = this.createLink();
    this.link = link;
    link.onOpen(() => {
      if (this.state !== "ended") this.state = "joined";
    });
    link.onClose(() => this.handleClose());
    link.connect();
  }

  private handleClose(): void {
    if (this.state === "leaving" || this.state === "ended") return;
    this.state = "reconnecting";
    this.openLink();
  }
}

