import { strict as assert } from "node:assert";
import { test } from "node:test";
import { MeetingSignaling } from "./meeting-signaling";

type Listener = () => void;
class FakeLink {
  private openListener?: Listener;
  private closeListener?: Listener;
  onOpen(listener: Listener): void { this.openListener = listener; }
  onClose(listener: Listener): void { this.closeListener = listener; }
  connect(): void { this.openListener?.(); }
  close(): void { this.closeListener?.(); }
}

test("ignores a repeated close from a superseded transport", () => {
  const links: FakeLink[] = [];
  const signaling = new MeetingSignaling(() => {
    const link = new FakeLink();
    links.push(link);
    return link;
  });

  signaling.join();
  links[0].close();
  assert.equal(signaling.state, "joined");
  assert.equal(links.length, 2);

  links[0].close();
  assert.equal(signaling.state, "joined");
  assert.equal(links.length, 2);
});

