type State = "active" | "ended";

export class MeetingRoster {
  state: State = "active";
  private remoteParticipantCount: number;

  constructor(participantIds: string[]) {
    this.remoteParticipantCount = participantIds.length;
  }

  get remainingRemoteParticipants(): number {
    return this.remoteParticipantCount;
  }

  onParticipantLeft(_participantId: string): void {
    if (this.state === "ended") return;
    this.remoteParticipantCount -= 1;
    if (this.remoteParticipantCount <= 0) this.state = "ended";
  }
}

