import { strict as assert } from "node:assert";
import { test } from "node:test";
import { MeetingRoster } from "./meeting-roster";

test("counts a participant departure only once", () => {
  const roster = new MeetingRoster(["attendee-a", "attendee-b"]);

  roster.onParticipantLeft("attendee-a");
  roster.onParticipantLeft("attendee-a");

  assert.equal(roster.remainingRemoteParticipants, 1);
  assert.equal(roster.state, "active");
});
